// Игрушечные «эмбеддинги» из 3 чисел. Настоящие содержат 1536+ чисел
// и приходят из embedding-модели, а не из головы.
const chunks = [
  { text: "Refunds are processed within 14 days.", vec: [0.9, 0.1, 0.0] },
  { text: "Our office is in Berlin.",              vec: [0.0, 0.2, 0.9] },
  { text: "Refund requests need an order number.", vec: [0.8, 0.3, 0.1] },
];

const cosine = (a, b) => {
  const dot = a.reduce((s, x, i) => s + x * b[i], 0);
  return dot / (Math.hypot(...a) * Math.hypot(...b));
};

const question = "How long does a refund take?";
const queryVec = [0.85, 0.2, 0.05]; // эмбеддинг вопроса

const ranked = chunks
  .map((c) => ({ ...c, score: cosine(queryVec, c.vec) }))
  .sort((x, y) => y.score - x.score);
for (const c of ranked) console.log(c.score.toFixed(3), c.text);

const top = ranked.slice(0, 2); // top-k, k = 2
const prompt =
  "Answer using only these sources:\n" +
  top.map((c) => "- " + c.text).join("\n") +
  "\n\nQuestion: " + question;
console.log(prompt);

